class NumericEntityUnescaper:
    HEX_CHARS = '0123456789abcdef'

    def __init__(self):
        pass

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                result, new_pos = self._parse_numeric_entity(string, pos, length)
                if new_pos != -1:
                    out.append(result)
                    pos = new_pos
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string, pos):
        return (pos + 2 < len(string) and 
                string[pos] == '&' and 
                string[pos + 1] == '#')

    def _parse_numeric_entity(self, string, pos, length):
        start = pos + 2
        is_hex = False
        first_char = string[start] if start < length else None

        if first_char == 'x' or first_char == 'X':
            start += 1
            is_hex = True

        if start == length:
            return None, -1

        end = start
        while end < length and self._is_hex_char(string[end]):
            end += 1

        if end < length and string[end] == ';':
            try:
                entity_value = int(string[start:end], 16 if is_hex else 10)
                return chr(entity_value), end + 1
            except (ValueError, OverflowError):
                return None, -1

        return None, -1

    @staticmethod
    def _is_hex_char(char):
        return char in NumericEntityUnescaper.HEX_CHARS
